#!/usr/bin/env python3
"""Render the Script vs. Screen library and structured episode reports."""
from pathlib import Path
import json,html
from transcript_header import site_header,ASSETS
from build_transcript_indexes import HEAD
E=html.escape
ROOT=Path('dist/script-vs-screen')
PDF='/assets/revision-reports/4x01-herrenvolk-revision-report.pdf'
CSS='''*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:28px}body{margin:0;background:#0b110e;color:#e8e6dc;font:15px/1.75 "DM Mono",monospace}a{color:inherit}a:focus-visible,button:focus-visible{outline:2px solid #e14a40;outline-offset:5px}.shell{width:min(1200px,calc(100% - 48px));margin:auto}.hero{padding:80px 0 64px;border-bottom:1px solid #354039;background:radial-gradient(ellipse at 90% 0,#24322a 0,transparent 58%)}.crumb,.eyebrow,.meta,.tag{font-size:11px;letter-spacing:.14em;text-transform:uppercase}.crumb{color:#a7afa7;margin-bottom:36px}.crumb a{text-decoration:none}.eyebrow{color:#e65a4f}.hero h1{font:400 clamp(64px,10vw,132px)/.95 "Oswald",sans-serif;letter-spacing:-.035em;text-transform:uppercase;margin:18px 0 28px}.hero p{max-width:740px;color:#b0b8b0}.actions{display:flex;flex-wrap:wrap;gap:12px;margin-top:30px}.button{display:inline-flex;align-items:center;padding:13px 20px;border:1px solid #697469;text-decoration:none;font-size:11px;letter-spacing:.08em;text-transform:uppercase}.button.primary{background:#e6e3d8;color:#141a15;border-color:#e6e3d8}.button:hover{border-color:#ed5c50}.stats{display:flex;flex-wrap:wrap;gap:32px;margin-top:42px}.stats>div{border-left:1px solid #b34438;padding-left:16px}.stats b{font:400 34px/1 "Oswald",sans-serif;display:block}.stats span{display:block;font-size:10px;text-transform:uppercase;color:#a2aaa2;margin-top:10px;letter-spacing:.1em}.section{padding:64px 0}.section h2,.section-heading{font:400 clamp(32px,5vw,54px)/1.1 "Oswald",sans-serif;text-transform:uppercase;margin:12px 0 26px}.intro{max-width:850px}.intro p,.body-copy{font:22px/1.65 Georgia,serif}.seasons{display:flex;flex-wrap:wrap;gap:10px;margin:28px 0 42px}.seasons a,.seasons span{padding:10px 16px;border:1px solid #37443b;font-size:11px;text-decoration:none}.seasons span{color:#889087}.seasons a{background:#e6e3d8;color:#151c16}.feature{display:grid;grid-template-columns:1fr 1fr;border:1px solid #465044;background:#141e17;text-decoration:none}.feature img{width:100%;height:100%;min-height:300px;object-fit:cover}.feature-copy{padding:40px}.feature h3{font:400 clamp(40px,6vw,70px)/1 "Oswald",sans-serif;text-transform:uppercase;margin:18px 0}.feature p{color:#b1b9af}.feature strong{display:inline-block;margin-top:16px;font-size:12px;color:#ee7b6e}.library-note{color:#9ba698;font-size:12px;margin-top:25px}.report-layout{display:grid;grid-template-columns:210px minmax(0,1fr);gap:48px;padding-top:56px}.contents{align-self:start;position:sticky;top:25px}.contents h2{font-size:11px;text-transform:uppercase;letter-spacing:.13em;color:#a9b3a5;margin:0 0 20px}.contents a{display:block;padding:10px 0;border-bottom:1px solid #354035;text-decoration:none;font-size:12px}.report-section{margin-bottom:64px;scroll-margin-top:25px}.report-section>h2{font:400 40px/1.1 "Oswald",sans-serif;text-transform:uppercase;margin:0 0 22px}.report-section>p{color:#bdc3b8}.finding{margin:32px 0 44px;padding-top:30px;border-top:1px solid #465142;scroll-margin-top:24px}.finding h3{font:400 clamp(26px,3vw,36px)/1.22 "Oswald",sans-serif;margin:12px 0}.permalink{text-decoration:none;color:#e8e6dc}.permalink:hover{color:#ef7366}.finding .meta{font-size:10px;color:#a8b4a1;margin-bottom:24px}.finding p{font:18px/1.75 Georgia,serif;color:#ccd0c5}.comparison{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1px;background:#858b7d;border:1px solid #858b7d;margin:24px 0}.comparison.single{grid-template-columns:1fr}.quote{background:#e6e3d8;color:#22291f;padding:25px}.quote.aired{background:#d4dacf}.quote h4{font-size:10px;font-weight:500;letter-spacing:.09em;margin:0 0 16px;text-transform:uppercase}.quote blockquote{font:14px/1.8 "DM Mono",monospace;margin:0;overflow-wrap:anywhere}.trail{border-left:2px solid #c85546;padding:10px 16px;font-size:11px;color:#c4ccbc}.drafts{width:100%;border-collapse:collapse;font-size:12px;margin:25px 0}.drafts th,.drafts td{text-align:left;padding:13px 8px;border-bottom:1px solid #465042}.drafts th{font-size:10px;text-transform:uppercase;color:#b8c0b2}.editorial{padding:30px;background:#182019;border-left:2px solid #d25747}.small-note{font-size:12px!important;font-family:"DM Mono",monospace!important;color:#aeb6a7!important}.report-footer{border-top:1px solid #3c4739;margin-top:60px;padding:35px 0;font-size:11px;color:#a8b09f}.report-footer .shell{display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap}@media(max-width:800px){.report-layout{grid-template-columns:1fr;gap:32px}.contents{position:static;display:flex;flex-wrap:wrap;gap:8px}.contents h2{width:100%}.contents a{border:1px solid #3c4739;padding:8px 12px}.feature{grid-template-columns:1fr}.feature img{max-height:300px}.hero{padding-top:48px}}@media(max-width:560px){.shell{width:calc(100% - 28px)}.comparison{grid-template-columns:1fr}.quote{padding:20px}.feature-copy{padding:25px}.hero h1{font-size:58px}.stats{gap:20px}.drafts{font-size:10px}.drafts th,.drafts td{padding:10px 4px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}@media print{.bf-header,.contents,.actions,.report-footer{display:none}.report-layout{display:block}body{background:white;color:black}.shell{width:100%}.hero{padding:10px 0}.finding{break-inside:avoid}.finding p,.meta,.report-section>p{color:black}.comparison{break-inside:avoid}}'''
def page(title,content):
 return f'<!doctype html><html lang="en"><head><title>{E(title)} — Boggsfiles</title>{HEAD}<meta name="description" content="Explore X-Files script revisions, deleted dialogue and changes in the aired episode.">{ASSETS}<link rel="stylesheet" href="/assets/comparisons.css"></head><body>{site_header("Script vs. Screen")}<main>{content}</main><footer class="report-footer"><div class="shell"><span>BOGGSFILES · SCRIPT VS. SCREEN</span><span><a href="/script-vs-screen/">All comparisons</a> · <a href="/">Home</a></span></div></footer></body></html>'
def paragraphs(text):
 # Keep the original report wording; break its long paragraphs at known paragraph starts.
 starts=['What the broadcast then removed','The cutting then goes','Every absence above','Recorded also because']
 for start in starts:text=text.replace(' '+start,'\n\n'+start)
 return ''.join('<p>'+E(p)+'</p>' for p in text.split('\n\n') if p)
def finding(f):
 quotes=''.join(f'<div class="quote {q["kind"]}"><h4>{E(q["label"])}</h4><blockquote>{E(q["text"])}</blockquote></div>' for q in f['quotes'])
 panels=f'<div class="comparison {"single" if len(f["quotes"])==1 else ""}">{quotes}</div>' if quotes else ''
 return f'<article class="finding" id="{f["id"]}"><h3><a class="permalink" href="#{f["id"]}">{E(f["title"])}</a></h3><div class="meta">{E(f["meta"])}</div>{paragraphs(f["intro"])}{panels}{"<div class=trail>Revision trail: "+E(f["trail"])+"</div>" if f["trail"] else ""}{paragraphs(f["analysis"])}</article>'
def build():
 data=json.loads(Path('tools/comparison-data/herrenvolk.json').read_text())
 ROOT.mkdir(exist_ok=True);(ROOT/'season-4/herrenvolk').mkdir(parents=True,exist_ok=True)
 Path('dist/assets/comparisons.css').write_text(CSS)
 seasons=''.join('<a href="#season-4">Season 4 · 1 report</a>' if n==4 else f'<span>Season {n} · forthcoming</span>' for n in range(1,10))
 landing=f'''<section class="hero"><div class="shell"><div class="crumb"><a href="/archive/">Archive</a> / Script vs. Screen</div><div class="eyebrow">The page versus the episode</div><h1>Script vs.<br>Screen</h1><p>What was written. What changed. What made it to air. Explore the drafts alongside the finished episode, from missing dialogue to the moments that stayed with us.</p><div class="stats"><div><b>1</b><span>Episode report</span></div><div><b>12</b><span>Herrenvolk findings</span></div><div><b>3</b><span>Drafts compared</span></div></div></div></section><section class="section"><div class="shell"><div class="eyebrow">Case files by season</div><h2>Between page and screen</h2><div class="seasons" aria-label="Season availability">{seasons}</div><div id="season-4"><div class="meta">Season 4 · 1996–1997</div><a class="feature" href="/script-vs-screen/season-4/herrenvolk/"><img src="/assets/transcript-stills/herrenvolk.jpg" alt="Scene from Herrenvolk" loading="lazy"><div class="feature-copy"><div class="eyebrow">Episode 01 · 4X01</div><h3>Herrenvolk</h3><p>Mulder’s missing pleas, Scully’s revised science, and the silence between them. Three archived drafts meet the aired season opener.</p><div class="meta">5 cuts / 5 changes / 2 shippy moments</div><strong>Read the comparison →</strong></div></a></div><p class="library-note">Read each report on the site, or download the original PDF. More episode files will appear here as the collection grows.</p></div></section>'''
 (ROOT/'index.html').write_text(page('Script vs. Screen',landing))
 categories=[('cut','Cut from screen','Dialogue cut or trimmed between the archived drafts and the DVD captions.'),('changed','Changed for screen','Reworded dialogue and additions in the aired episode.'),('shippy','♥ Shippy moments','He comes back from Canada with nothing, and she is the one waiting.')]
 sections=''.join(f'<section class="report-section" id="{key}"><div class="eyebrow">{len([f for f in data["findings"] if f["category"]==key])} findings</div><h2>{title}</h2><p>{desc}</p>'+''.join(finding(f) for f in data['findings'] if f['category']==key)+'</section>' for key,title,desc in categories)
 nav=''.join(f'<a href="#{key}">{title}</a>' for key,title in [('summary','Case summary'),('drafts','Draft history'),('cut','Cut from screen'),('changed','Changed for screen'),('shippy','Shippy moments'),('takeaway','Editorial takeaway'),('sources','Sources & methodology')])
 report=f'''<section class="hero"><div class="shell"><div class="crumb"><a href="/script-vs-screen/">Script vs. Screen</a> / <a href="/script-vs-screen/#season-4">Season 4</a> / Herrenvolk</div><div class="eyebrow">Revision report · 4X01 · Season 4, Episode 1</div><h1>Herrenvolk</h1><p>Three archived script drafts, compared with the Region 1 DVD closed captions.</p><div class="meta">Written by Chris Carter · Directed by R. W. Goodwin<br>Aired October 4, 1996</div><div class="actions"><a class="button primary" href="#cut">Read the findings ↓</a><a class="button" href="{PDF}" download>Download original PDF ↓</a><a class="button" href="/transcripts/season-4/herrenvolk/">Read transcript →</a><a class="button" href="/x-files-scripts-by-season/season-4/">Browse Season 4 scripts →</a></div></div></section><div class="shell report-layout"><nav class="contents" aria-label="Report contents"><h2>In this report</h2>{nav}</nav><div><section class="report-section intro" id="summary"><div class="eyebrow">The case in brief</div><h2>Case summary</h2>{paragraphs(data['summary'])}<div class="stats"><div><b>5</b><span>Cut or trimmed</span></div><div><b>5</b><span>Changed for screen</span></div><div><b>2</b><span>Shippy moments</span></div></div></section><section class="report-section" id="drafts"><h2>Draft history</h2><table class="drafts"><thead><tr><th scope="col">Date</th><th scope="col">Revision</th><th scope="col">Format</th><th scope="col">In this report</th></tr></thead><tbody><tr><td>July 5, 1996</td><td>White</td><td>Production draft</td><td>Not held</td></tr><tr><td>July 8, 1996</td><td>Blue</td><td>Full · 57 pages</td><td>Compared</td></tr><tr><td>July 18, 1996</td><td>Pink</td><td>11 revision pages</td><td>Compared</td></tr><tr><td>July 21, 1996</td><td>Green</td><td>Full · 57 pages</td><td>Compared</td></tr></tbody></table></section>{sections}<section class="report-section editorial" id="takeaway"><div class="eyebrow">Reading the revisions</div><h2>Editorial takeaway</h2><div class="body-copy">{paragraphs(data['takeaway'])}</div></section><section class="report-section" id="sources"><h2>Sources & methodology</h2><p class="small-note">Adapted from the supplied Boggsfiles Herrenvolk Revision Report. Time references are from the Region 1 DVD caption track. The methodology below describes the report’s original research.</p>{paragraphs(data['methodology'])}<p class="small-note">Source map: Blue, July 8 — 57 pages, 39 revision marks; Pink, July 18 — 11 pages; Green, July 21 — 57 pages, 88 revision marks. Aired source: Season 4, Disc 1, Region 1 DVD.</p><p class="small-note">Web edition: the cover’s “Providence” label is not reproduced. The bunker summary and headings have been clarified to reflect retained dialogue and the limits of caption evidence. The original PDF is preserved unchanged.</p><div class="actions"><a class="button" href="{PDF}">Open original PDF ↗</a><a class="button" href="{PDF}" download>Download PDF ↓</a></div></section></div></div>'''
 (ROOT/'season-4/herrenvolk/index.html').write_text(page('Herrenvolk — Script vs. Screen',report))
if __name__=='__main__':build()
